/*
 * Boundless generator for buildai-generator-runtime-engine — item 179.
 * Dual node+browser: node prints JSONL records; browser registers with JAHDB.
 * Deterministic: same seed + topic = same record. HARD_CAP = 1e15.
 */
'use strict';
var SLUG = 'buildai-generator-runtime-engine';
var PREFIX = 'JAH-BAI-';
var HARD_CAP = 1e15;
var ARCHETYPES = [{"kind": "template-render", "title": "Rendering a Template", "body": "Templates substitute {{name}}, {{description}}, and {{field:name}} markers. The demo renders a miniature template at generation time.", "demoCode": "var tpl='// {{name}}';return tpl.split('{{name}}').join('demo-tool');", "ladder": "simple", "vstat": "tested", "caps": ["template rendering"]}, {"kind": "spec-validate", "title": "Validating a Specification", "body": "Specs need a valid name and at least one template. The demo validates a nameless spec and prints the errors.", "demoCode": "function v(s){var e=[];if(!s.name)e.push('name required');if(!s.templates||!s.templates.length)e.push('templates required');return e;}return 'errors: '+v({}).join('; ');", "ladder": "simple", "vstat": "tested", "caps": ["input validation"]}, {"kind": "placeholder-scan", "title": "Counting Placeholders in a Template", "body": "The renderer finds every {{...}} marker before substitution. The demo counts markers in a sample template.", "demoCode": "var tpl='{{name}} {{field:n}} {{name}}';var m=tpl.match(/\\{\\{[^}]+\\}\\}/g);return 'placeholders: '+m.length;", "ladder": "simple", "vstat": "tested", "caps": ["template rendering"]}, {"kind": "fahrenheit-math", "title": "The Converter Math, Verified", "body": "The temperature converter's core is (f-32)*5/9. The demo computes it for 212 at generation time.", "demoCode": "var f=212;return f+'F = '+((f-32)*5/9).toFixed(2)+'C';", "ladder": "simple", "vstat": "tested", "caps": ["program execution"]}, {"kind": "test-assertion", "title": "How a Test Passes", "body": "A test passes on exit 0 plus expected output. The demo evaluates a miniature assertion.", "demoCode": "var exit=0,out='words: 3';var pass=exit===0&&out.indexOf('words: 3')>=0;return 'test pass: '+pass;", "ladder": "competitive", "vstat": "tested", "caps": ["test execution"]}, {"kind": "ladder-gates", "title": "Climbing the Verification Ladder", "body": "Statuses are earned by gates: validate\u2192proposed, write\u2192generated, run\u2192executable, tests\u2192tested. The demo walks the ladder.", "demoCode": "var gates=['validate','write','run','tests'];var st=['proposed','generated','executable','tested'];return gates.map(function(g,i){return g+'->'+st[i];}).join(' | ');", "ladder": "competitive", "vstat": "tested", "caps": ["verification lifecycle"]}, {"kind": "file-list", "title": "What a Generated Project Contains", "body": "A generated project is a directory of rendered files. The demo lists a miniature project's files.", "demoCode": "var files=['main.js','README.md'];return files.length+' files: '+files.join(', ');", "ladder": "simple", "vstat": "tested", "caps": ["file generation"]}, {"kind": "paste-note", "title": "Beyond JavaScript: Honest Scope", "body": "Today the engine targets node/JavaScript only; other runtimes are future work. This record states the boundary \u2014 proposed, not promised.", "demoCode": "return 'scope today: node/JavaScript only; additional runtimes are proposed future work';", "ladder": "simple", "vstat": "proposed", "caps": ["honest limits"]}];

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function generate(seed, opts) {
  opts = opts || {};
  seed = Math.floor(Math.abs(Number(seed) || 1));
  var rng = mulberry32(seed);
  var ai = ARCHETYPES[Math.floor(rng() * ARCHETYPES.length)];
  var topic = opts.topic || 'the Signature engineering system';
  var idx = Math.floor(rng() * 1000);
  var demoOutput;
  try { demoOutput = String((new Function(ai.demoCode))()); }
  catch (e) { demoOutput = 'demo error: ' + String(e && e.message || e); }
  var title = ai.title + ' — ' + topic + ' #' + (idx + 1);
  return {
    id: PREFIX + 'G' + String(seed).padStart(4, '0') + '-' + String(idx).padStart(3, '0'),
    slug: SLUG, title: title, t: title, g: 'engineering systems', c: 1,
    description: ai.title + ': a generated record for ' + topic + '.',
    body: ai.body + ' This record was produced by the boundless generator for ' + topic +
      '; its demonstration ran at generation time and the captured output is stored below.',
    capabilities: ai.caps,
    demo: { program: ai.demoCode, output: demoOutput.slice(0, 2000) },
    provenance: 'Generated by the boundless generator for ' + SLUG + ' (item 179), seed ' + seed + '.',
    licensing: 'Original Signature software. Property of Justin Addam Higgins (JAH).',
    src: 'generated', edition: 'signature', ladder_rank: ai.ladder,
    generator: 'jahdb-buildai-generator-runtime-engine-1.0', verification_status: ai.vstat,
    links: [], record_kind: 'generator engine record'
  };
}

function validate(r) {
  var errors = [];
  ['id', 'title', 'body', 'demo', 'src', 'edition', 'verification_status'].forEach(function (f) {
    if (r[f] === undefined || r[f] === null || r[f] === '') errors.push('missing ' + f);
  });
  if (r.demo && (r.demo.program === undefined || r.demo.output === undefined))
    errors.push('demo needs program and output');
  return { ok: errors.length === 0, errors: errors };
}

var api = { generate: generate, validate: validate, HARD_CAP: HARD_CAP, SLUG: SLUG };

if (typeof module !== 'undefined' && module.exports) module.exports = api;
if (typeof window !== 'undefined' && window.JAHDB && window.JAHDB.registerGenerator)
  window.JAHDB.registerGenerator(SLUG, api);
if (typeof process !== 'undefined' && process.argv && process.argv[1] &&
    process.argv[1].indexOf('gen-') >= 0) {
  (function main() {
    var n = 8, seed = 1, topic = null;
    var a = process.argv.slice(2);
    for (var i = 0; i < a.length; i++) {
      if (a[i] === '--n') n = parseInt(a[++i], 10);
      if (a[i] === '--seed') seed = parseInt(a[++i], 10);
      if (a[i] === '--topic') topic = a[++i];
    }
    if (!(n >= 1 && n <= HARD_CAP)) { console.error('n out of range'); process.exit(1); }
    for (var k = 0; k < n; k++) {
      var r = generate(seed + k, { topic: topic });
      var v = validate(r);
      if (!v.ok) { console.error('invalid record: ' + v.errors.join('; ')); process.exit(1); }
      console.log(JSON.stringify(r));
    }
  })();
}
